    61  UA_StatusCode
    62  UA_Server_forEachChildNodeCall(UA_Server *server, UA_NodeId parentNodeId,
    63                                 UA_NodeIteratorCallback callback, void *handle) {
    64      const UA_Node *parent =
    65          server->config.nodestore.getNode(server->config.nodestore.context,
    66                                           &parentNodeId);
    67      if(!parent)
    68          return UA_STATUSCODE_BADNODEIDINVALID;
    69
    70      /* TODO: We need to do an ugly copy of the references array since users may
    71       * delete references from within the callback. In single-threaded mode this
    72       * changes the same node we point at here. In multi-threaded mode, this
    73       * creates a new copy as nodes are truly immutable.
    74       * The callback could remove a node via the regular public API.
    75       * This can remove a member of the nodes-array we iterate over...
    76       * */
    77      UA_Node *parentCopy = UA_Node_copy_alloc(parent);
    78      if(!parentCopy) {
    79          server->config.nodestore.releaseNode(server->config.nodestore.context, parent);
    80          return UA_STATUSCODE_BADUNEXPECTEDERROR;
    81      }
    82
    83      UA_StatusCode retval = UA_STATUSCODE_GOOD;
    84      for(size_t i = parentCopy->referencesSize; i > 0; --i) {
    85          UA_NodeReferenceKind *ref = &parentCopy->references[i - 1];
    86          for(size_t j = 0; j<ref->targetIdsSize; j++)
    87              retval |= callback(ref->targetIds[j].nodeId, ref->isInverse,
    88                                 ref->referenceTypeId, handle);
    89      }
    90      UA_Node_deleteMembers(parentCopy);
    91      UA_free(parentCopy);
    92
    93      server->config.nodestore.releaseNode(server->config.nodestore.context, parent);
    94      return retval;
    95  }
